class Solution { public int[] windowMaximums(int[] nums, int k) { java.util.ArrayDeque<Integer> q=new java.util.ArrayDeque<>();int[] r=new int[nums.length-k+1];int at=0;for(int i=0;i<nums.length;i++){while(!q.isEmpty()&&q.peekFirst()<=i-k)q.removeFirst();while(!q.isEmpty()&&nums[q.peekLast()]<=nums[i])q.removeLast();q.addLast(i);if(i>=k-1)r[at++]=nums[q.peekFirst()];}return r; } }
